    Swift,
    TypeScript,
    Zig,
}

impl Lang {
    fn as_str(&self) -> &'static str {
        match self {
            Lang::Bash => "bash",
            Lang::C => "c",
            Lang::Cpp => "cpp",
            Lang::Crystal => "crystal",
            Lang::CSharp => "csharp",
            Lang::Dart => "dart",
            Lang::Elixir => "elixir",
