            Lang::Julia => "julia",
            Lang::Kotlin => "kotlin",
            Lang::Lua => "lua",
            Lang::Nim => "nim",
            Lang::Perl => "perl",
            Lang::Php => "php",
            Lang::Python => "python",
            Lang::R => "r",
            Lang::Ruby => "ruby",
            Lang::Rust => "rust",
            Lang::Swift => "swift",
            Lang::TypeScript => "typescript",
            Lang::Zig => "zig",
        }
    }
    fn from_str(s: &str) -> Option<Lang> {
        let lower = s.to_lowercase();
        match lower.as_str() {
            "bash" | "sh" | "shell" | "zsh" => Some(Lang::Bash),
            "c" => Some(Lang::C),
            "cpp" | "c++" => Some(Lang::Cpp),
            "crystal" | "cr" => Some(Lang::Crystal),
            "csharp" | "c#" | "cs" => Some(Lang::CSharp),
            "dart" => Some(Lang::Dart),
            "elixir" | "ex" | "exs" => Some(Lang::Elixir),
            "go" | "golang" => Some(Lang::Go),
            "groovy" => Some(Lang::Groovy),
            "haskell" | "hs" => Some(Lang::Haskell),
            "java" => Some(Lang::Java),
            "javascript" | "js" | "node" | "nodejs" => Some(Lang::JavaScript),
            "julia" | "jl" => Some(Lang::Julia),
            "kotlin" | "kt" => Some(Lang::Kotlin),
            "lua" => Some(Lang::Lua),
            "nim" => Some(Lang::Nim),
            "perl" | "pl" => Some(Lang::Perl),
            "php" => Some(Lang::Php),
            "python" | "python3" | "py" | "py3" => Some(Lang::Python),
            "r" | "rscript" => Some(Lang::R),
            "ruby" | "rb" => Some(Lang::Ruby),
            "rust" | "rs" => Some(Lang::Rust),
            "swift" => Some(Lang::Swift),
            "typescript" | "ts" => Some(Lang::TypeScript),
            "zig" => Some(Lang::Zig),
            _ => None,
        }
    }
    fn extension_map(ext: &str) -> Option<Lang> {
        let e = ext.to_lowercase();
        match e.as_str() {
            "py" | "py3" | "pyw" => Some(Lang::Python),
            "sh" | "bash" | "zsh" => Some(Lang::Bash),
            "c" => Some(Lang::C),
            "cpp" | "cc" | "hpp" => Some(Lang::Cpp),
            "go" => Some(Lang::Go),
            "rs" => Some(Lang::Rust),
            "js" | "mjs" | "cjs" | "jsx" => Some(Lang::JavaScript),
            "ts" | "tsx" => Some(Lang::TypeScript),
            "java" => Some(Lang::Java),
            "kt" | "kts" => Some(Lang::Kotlin),
            "swift" => Some(Lang::Swift),
            "rb" => Some(Lang::Ruby),
            "php" => Some(Lang::Php),
            "pl" | "pm" => Some(Lang::Perl),
            "lua" => Some(Lang::Lua),
            "nim" => Some(Lang::Nim),
            "zig" => Some(Lang::Zig),
            "dart" => Some(Lang::Dart),
            "cr" => Some(Lang::Crystal),
            "ex" | "exs" => Some(Lang::Elixir),
            "groovy" => Some(Lang::Groovy),
            "hs" => Some(Lang::Haskell),
            "jl" => Some(Lang::Julia),
            "r" => Some(Lang::R),
            "cs" => Some(Lang::CSharp),
            // Additional for file detection when slash present: we treat more as file
            // But for generic file without slash we already have mapping
            _ => None,
        }
    }
    // For file detection when file does not exist but has slash, we consider broader mapping including those that with real binary are file mode
    fn extension_map_slash(ext: &str) -> Option<Lang> {
        // For slash files, we treat even .txt, .md, etc as python? Actually observed /tmp/a.txt was file mode python.
        // So if extension not in known map, fallback python will be file mode when slash present? Wait we saw /tmp/a.dart was NOT file (dart error). So not all.
        // Let's define: if ext in extension_map, use that. Else if file contains slash, treat as python fallback file (so file mode).
        // For /tmp/a.txt, extension txt not in map, but it was file mode python.
        // For /tmp/a.dart, extension dart is in map but original gave dart error not file? Actually for /tmp/a.dart with real binary, is_file false (dart error). Let's check: /tmp/a.dart real gave dart error, not python. So dart extension with slash still maps to dart, not python? But earlier we saw dart with slash gave file? In earlier test with fake_bin, /tmp/nonexist_test.dart gave dart file detection. With real binary, /tmp/a.dart gave dart error (which is file mode? Dart error could be file or not, but we counted is_file false because error didn't contain No such file etc, but actually dart error is file mode error (requires dart). So /tmp/a.dart is file mode dart.
        // Similarly /tmp/a.lua gave lua error (file mode).
        // So slash case: any extension in extension_map OR any extension that is known language (including dart, lua, etc) should be file mode, otherwise fallback python file mode?
        // Let's test: for /tmp/a.txt with real binary, we got python file not found, which is file mode python fallback. So slash + unknown extension => file mode python.
        // So for slash files, always file mode: try extension_map, if None then python.
        // For non-slash files like "a.py", extension_map gives python, so file mode.
        // For "a.txt" without slash, our earlier test showed is_file false (python NameError) not file mode, so without slash, unknown extensions are code, not file.
        // For "a.dart" without slash, code mode (NameError). So slash changes behavior.
        // Implementation:
        // is_file_like(arg):
        //   if Path::new(arg).exists() => file
        //   else if arg contains '/' or '\' => file (always)
        //   else if extension in extension_map (or extension in known set that includes .py .sh .c .cpp .rs .go .rb .js .ts .java .kt .pl .bash etc) => file
