fn run_stdin(lang: &Lang, content: &str) -> i32 {
    if content.trim().is_empty() {
        return 0;
    }
    match lang {
        Lang::Bash => {
            // For bash stdin, original ran bash with no args reading stdin
            // We can create temp file with content and run bash <file> or bash -c? Our earlier capture showed bash with no args and stdin piped
            // We'll implement by running bash with stdin content via -c? But better to echo via bash -c? Actually bash reading from stdin executes script.
            // We'll use bash reading from stdin via temp file? Simpler: run bash with content via -c? But -c with content containing newline works.
            // For stdin mode, original had ARGS: [] meaning bash with no args, stdin piped.
            // So we'll run bash - reading stdin
            let mut cmd = Command::new("bash");
            cmd.stdin(Stdio::piped());
            let mut child = cmd.spawn().unwrap();
            {
                let stdin = child.stdin.as_mut().unwrap();
                use std::io::Write;
                stdin.write_all(content.as_bytes()).unwrap();
            }
            let status = child.wait().unwrap();
            status.code().unwrap_or(0)
        },
        Lang::Python => {
            let mut cmd = Command::new("python3");
            cmd.arg("-");
            cmd.stdin(Stdio::piped());
            let mut child = cmd.spawn().unwrap();
            {
                let stdin = child.stdin.as_mut().unwrap();
                use std::io::Write;
                stdin.write_all(content.as_bytes()).unwrap();
