fn main() {
    let args: Vec<String> = env::args().collect();
    // Manual parsing replicating clap
    let mut lang_flag: Option<String> = None;
    let mut file_flag: Option<String> = None;
    let mut code_flag: Option<String> = None;
    let mut no_detect = false;
    let mut positional: Vec<String> = Vec::new();

    let mut i = 1;
    while i < args.len() {
        let arg = &args[i];
        if arg == "--" {
            i += 1;
            while i < args.len() {
                positional.push(args[i].clone());
                i += 1;
            }
            break;
        }
        if arg == "-V" || arg == "--version" {
            print!("{}", VERSION);
            return;
        }
        if arg == "-h" || arg == "--help" {
            print!("{}", HELP);
            return;
        }
        if arg == "--no-detect" {
            no_detect = true;
            i += 1;
            continue;
        }
        if arg == "-l" || arg == "--lang" {
            if i + 1 >= args.len() {
                eprint!("error: a value is required for '--lang <LANG>' but none was supplied\n\nFor more information, try '--help'.\n");
                std::process::exit(2);
            }
            lang_flag = Some(args[i+1].clone());
            i += 2;
            continue;
        }
        if let Some(val) = arg.strip_prefix("--lang=") {
            if val.is_empty() {
                eprint!("error: a value is required for '--lang <LANG>' but none was supplied\n\nFor more information, try '--help'.\n");
                std::process::exit(2);
            }
            lang_flag = Some(val.to_string());
            i += 1;
            continue;
        }
        if arg == "-f" || arg == "--file" {
            if i + 1 >= args.len() {
                eprint!("error: a value is required for '--file <PATH>' but none was supplied\n\nFor more information, try '--help'.\n");
                std::process::exit(2);
            }
            file_flag = Some(args[i+1].clone());
            i += 2;
            continue;
        }
        if let Some(val) = arg.strip_prefix("--file=") {
            if val.is_empty() {
                eprint!("error: a value is required for '--file <PATH>' but none was supplied\n\nFor more information, try '--help'.\n");
                std::process::exit(2);
            }
            file_flag = Some(val.to_string());
            i += 1;
            continue;
        }
        if arg == "-c" || arg == "--code" {
            if i + 1 >= args.len() {
                eprint!("error: a value is required for '--code <CODE>' but none was supplied\n\nFor more information, try '--help'.\n");
                std::process::exit(2);
            }
            // Check if next arg is another flag? In clap, value required, but if next starts with -, it would be considered value? We saw for --code with missing arg, it errors. For our simple, take next.
            // However we saw --code requires a code argument error when code is missing? Let's see our earlier test: ./executable --lang python --code "print" -- --code gave error about requires code argument? Actually we had --lang python -- --code gave "Error: --code/--inline requires a code argument". That's different.
            // For case where --code is last and no value, clap error already handled.
            code_flag = Some(args[i+1].clone());
            i += 2;
            continue;
        }
        if let Some(val) = arg.strip_prefix("--code=") {
            if val.is_empty() {
                eprint!("error: a value is required for '--code <CODE>' but none was supplied\n\nFor more information, try '--help'.\n");
                std::process::exit(2);
            }
            code_flag = Some(val.to_string());
            i += 1;
            continue;
        }
        // Unknown option
        if arg.starts_with('-') {
            let usage = if file_flag.is_some() && code_flag.is_some() {
                "executable --lang <LANG> --code <CODE> --file <PATH> [ARGS]"
            } else if file_flag.is_some() && lang_flag.is_some() {
                "executable --lang <LANG> --file <PATH> [ARGS]"
            } else if code_flag.is_some() && lang_flag.is_some() {
                "executable --lang <LANG> --code <CODE> [ARGS]"
            } else if file_flag.is_some() {
                "executable --file <PATH> [ARGS]"
            } else if lang_flag.is_some() {
                "executable --lang <LANG> [ARGS]"
            } else {
                "executable [OPTIONS] [ARGS]"
            };
            eprint!("error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\nUsage: {}...\n\nFor more information, try '--help'.\n", arg, arg, arg, usage);
