        // If file is python and path doesn't exist, python will give can't open file error (which we want)
        // For c etc, we have special error for copy failure
        let code = run_file(&lang, &file_path);
        std::process::exit(code);
    }

    if let Some(code_str) = code_flag {
        // code mode via flag
        // Check for empty code? If code_str empty? Original had error "Error: --code/--inline requires a code argument" when --code is passed after --?
        // That error occurred when using "-- --code"? Let's see: ./executable --lang python -- --code gave error about requires code argument. That is because after --, "--code" is positional, not flag, but our parsing treats -- as separator, so "--code" becomes positional. But in that case code_flag is None? Actually we have --lang python + positional "--code"? We should have detected special case.
        // The error "Error: --code/--inline requires a code argument" occurs when --code flag is provided without value but with -- separator? Let's test again: ./executable --lang python --code gave missing value error from clap, not this error.
        // The case that gave this error was: ./executable --lang python -- --code  (with -- separator before --code)
        // That means --code is treated as positional code? But error says requires code argument. So this is when positional contains "--code" or "--inline"?
        // Let's see: args ["--lang","python","--","--code"] -> our parsing: after --, positional = ["--code"], so no code_flag. Then we would treat positional as file/code? That would be code "--code" which would be python NameError? But original gave error "Error: --code/--inline requires a code argument". So this is an edge case where --code as positional triggers that error.
        // Perhaps original tool also has --inline alias that expects code argument, and when you pass "-- --code" it thinks you are trying to pass --code as value but missing? Actually clap with -- separator treats "--code" as positional, but custom validation might treat "--code" string as requiring argument?
        // Let's replicate: If positional contains exactly "--code" or "--inline", then error "Error: --code/--inline requires a code argument"
        // Check: ./executable --lang python -- --code gave that error. So positional arg "--code" triggers this error.
        // Similarly what about "-- --inline"? Likely same.

        // For our implementation, we'll check if positional contains "--code" when code_flag is None? But in this branch code_flag is Some, so not relevant.

        let lang = if let Some(l) = lang_from_flag.clone() {
            l
        } else {
            if no_detect {
                Lang::Python
            } else {
                heuristic_detect_code(&code_str)
            }
        };
        let exit = run_code(&lang, &code_str);
        std::process::exit(exit);
    }

    // No explicit file/code flags, handle positional
    if positional.is_empty() {
        // Read stdin
        let mut stdin_content = String::new();
        // Check if stdin is terminal
        if !io::stdin().is_terminal() {
            io::stdin().read_to_string(&mut stdin_content).unwrap();
        } else {
            // No args and tty -> REPL? For now exit 0
            std::process::exit(0);
        }
        if stdin_content.trim().is_empty() {
            std::process::exit(0);
        }
        // If stdin contains only whitespace, exit 0?
        // Now determine lang
        let lang = if let Some(l) = lang_from_flag.clone() {
            l
        } else {
            if no_detect {
                Lang::Python
            } else {
                heuristic_detect_code(&stdin_content)
            }
        };
        let exit = run_stdin(&lang, &stdin_content);
        std::process::exit(exit);
    } else if positional.len() == 1 {
        let arg = &positional[0];
        // Special case: arg == "--code" or "--inline" -> error requires code argument
        if arg == "--code" || arg == "--inline" {
            eprintln!("Error: --code/--inline requires a code argument");
            std::process::exit(1);
        }
        // Check if arg is known language and no file exists and not file-like?
        // Determine if arg is file
        let is_file = is_file_path_arg(arg);
        if is_file {
            // file mode
            let lang = if let Some(l) = lang_from_flag.clone() {
                l
            } else {
                if no_detect {
                    Lang::Python
                } else {
                    // For file detection without flag, if no_detect, fallback python? But earlier we saw --no-detect file .sh gave python error, not bash. So when no_detect is true, we ignore extension and fallback python.
                    lang_from_file_path(arg)
                }
            };
            // If no_detect flag set, override lang to python? We observed --no-detect file .sh gave python error, so yes, no_detect disables extension detection.
            let final_lang = if no_detect && lang_from_flag.is_none() {
                Lang::Python
            } else {
                lang
            };
            let exit = run_file(&final_lang, arg);
            std::process::exit(exit);
        } else {
            // Check if arg is known language
            if let Some(l) = Lang::from_str(arg) {
                // lang mode with stdin
                let lang = if let Some(lf) = lang_from_flag.clone() {
                    // If lang flag also present, what to do? The positional lang is then considered code? But we have len==1, so if flag present, this arg is file/code, not lang. So we already handled flag case: if lang_flag present, we wouldn't be here checking file? Actually we did check is_file earlier, but if lang_flag present and arg is known language string like "bash", is_file false, so we go here and detect as lang again? That would be double lang. For --lang python + positional "bash", we should treat "bash" as code, not lang. So when lang_from_flag is Some, we should NOT treat positional as lang, but as code/file.
                // So if lang_from_flag is Some, treat arg as code/file already handled? For code, is_file false, so we would treat as lang again incorrectly. So we need to branch on lang_from_flag presence.
                // If lang_flag present, then single positional arg is file or code, not lang.
                    // So if we are here, it means is_file false, so code mode with lang_from_flag
                    if lf != l {
                        // lang flag overrides? Actually if flag present, the positional arg should be code even if it's known lang string, so we should not treat as lang.
                        // Let's handle: if lang_from_flag is Some, then this positional arg is code
                        let exit = run_code(&lf, arg);
                        std::process::exit(exit);
                    } else {
                        // Same lang as flag? Still treat as stdin? But original for ["python"] with flag --lang python and positional python? That case would be: --lang python python (positional). What should happen? The second python is file? No file exists, so it would be considered file? Actually "python" without slash is not file-like (since no extension, no slash), so is_file false, so we would treat as code "python" which would be NameError. But maybe should treat as lang mode? Let's not overcomplicate.
                    }
                }
                lang_from_flag = Some(l.clone());
                // Now lang mode, read stdin
                let mut stdin_content = String::new();
                if !io::stdin().is_terminal() {
                    io::stdin().read_to_string(&mut stdin_content).unwrap();
                } else {
                    std::process::exit(0);
                }
                if stdin_content.trim().is_empty() {
                    std::process::exit(0);
                }
                let exit = run_stdin(&l, &stdin_content);
                std::process::exit(exit);
            } else {
                // code mode
                let lang = if let Some(l) = lang_from_flag.clone() {
                    l
                } else {
                    if no_detect {
                        Lang::Python
                    } else {
                        heuristic_detect_code(arg)
                    }
                };
                let exit = run_code(&lang, arg);
                std::process::exit(exit);
            }
        }
    } else {
        // len >=2
        // Check if first is known language and no lang_flag
        if lang_from_flag.is_none() {
            if let Some(first_lang) = Lang::from_str(&positional[0]) {
                // First is lang
                if positional.len() == 2 {
                    let second = &positional[1];
                    // Check if second is file
                    let is_file = is_file_path_arg(second);
                    if is_file {
                        let exit = run_file(&first_lang, second);
                        std::process::exit(exit);
                    } else {
                        let exit = run_code(&first_lang, second);
                        std::process::exit(exit);
                    }
                } else {
                    // >2 args, join remaining as code
                    let code = positional[1..].join(" ");
                    // Special handling: if code is empty? etc
                    let exit = run_code(&first_lang, &code);
                    std::process::exit(exit);
                }
            } else {
                // First not lang, treat all as code joined
                let code = positional.join(" ");
                let lang = if no_detect {
                    Lang::Python
                } else {
                    heuristic_detect_code(&code)
                };
                let exit = run_code(&lang, &code);
                std::process::exit(exit);
            }
        } else {
            // lang_flag present, so all positional are code joined
            let code = positional.join(" ");
            if code.trim().is_empty() {
                // No code, check stdin?
                let mut stdin_content = String::new();
                if !io::stdin().is_terminal() {
                    io::stdin().read_to_string(&mut stdin_content).unwrap();
                }
                if !stdin_content.trim().is_empty() {
                    let exit = run_stdin(&lang_from_flag.clone().unwrap(), &stdin_content);
                    std::process::exit(exit);
                } else {
                    std::process::exit(0);
                }
            }
            let exit = run_code(&lang_from_flag.clone().unwrap(), &code);
            std::process::exit(exit);
        }
    }
}
