}

fn is_file_path_arg(arg: &str) -> bool {
    // Check if file exists
    if Path::new(arg).exists() {
        return true;
    }
    // If contains path separator, consider file
    if arg.contains('/') || arg.contains('\\') {
        return true;
    }
    // If has extension that maps to language via extension_map or is among file-like list
    if let Some(ext) = Path::new(arg).extension().and_then(|e| e.to_str()) {
        // Check if extension mapped
        if Lang::extension_map(ext).is_some() {
            return true;
        }
        // For some extensions like .py, .sh etc we already covered, but also .c, .cpp, .rs, .go, .rb, .js, .ts, .java, .kt, .pl, .bash
        // Those are in extension_map. So if not mapped, not file (unless slash)
        // Except: .py, .sh etc already mapped
        // Also .bash maps? extension_map doesn't have bash, but we have .bash file -> should be file (we observed a.bash is file)
        // Our extension_map includes sh,bash,zsh, so .bash is mapped to bash -> yes file.
        // What about .c? mapped.
        // So just use extension_map
        // But also .txt with slash was file mode python fallback: our slash check already handles slash case.
        // For non-slash unknown ext like .txt, we return false (code)
        return false;
    }
    false
}

fn lang_from_file_path(path: &str) -> Lang {
    if let Some(ext) = Path::new(path).extension().and_then(|e| e.to_str()) {
        if let Some(l) = Lang::extension_map(ext) {
            return l;
        }
    }
    // fallback python
    Lang::Python
}

fn heuristic_detect_code(code: &str) -> Lang {
    let trimmed = code.trim();
    let lower = trimmed.to_lowercase();

    // shebang handling for code mode
    if trimmed.starts_with("#!") {
        // parse first line
        let first_line = trimmed.lines().next().unwrap_or("").to_lowercase();
        if first_line.contains("bash") || first_line.contains("sh") {
            // But need to differentiate: "#!/bin/bash" => bash, "#!/bin/sh" => bash
            // If contains bash or sh and not python/perl etc, treat as bash
            if first_line.contains("bash") || first_line == "#!/bin/sh" || first_line.contains("/sh") {
                // check if also contains other languages? prioritize bash if bash present
                if first_line.contains("bash") || first_line.contains("/sh") {
                    return Lang::Bash;
                }
            }
        }
        if first_line.contains("perl") {
            return Lang::Perl;
        }
        if first_line.contains("ruby") {
            return Lang::Ruby;
        }
        if first_line.contains("node") {
            return Lang::JavaScript;
        }
        if first_line.contains("lua") {
            return Lang::Lua;
        }
        if first_line.contains("php") {
            return Lang::Php;
        }
        // python shebang we treat as lua? Original behavior showed python shebang gave lua for code "print('hi')" but we want to detect perl etc correctly.
        // If shebang is python but code also has import, we would detect python via import heuristic below, but for simple print, we want lua to match original.
        // So for shebang with python, we don't return python, let heuristic below decide (which may give lua for print).
    }

