    // bash: echo without quotes or export
    // Pattern: starts with "echo " followed by not ' or "
    if lower.starts_with("echo ") {
        // check if after echo, first char is ' or "
        let after = trimmed[4..].trim_start();
        // after could be -n, -e etc
        let mut rest = after;
        // handle flags like -n, -e
        if rest.starts_with("-") {
            // flags then space
            if let Some(idx) = rest.find(' ') {
                rest = rest[idx..].trim_start();
            }
        }
        if !rest.is_empty() {
            let first_char = rest.chars().next().unwrap();
            if first_char != '\'' && first_char != '"' {
                return Lang::Bash;
            }
        } else {
            // just "echo" alone? original treated as python? In earlier test, "echo" alone gave python NameError, not bash. So empty after echo not bash?
            // Let's check: single arg "echo" -> we saw python error. So echo alone not bash.
            // So require argument non-empty and not quoted.
        }
    }
    if lower.starts_with("export ") {
        return Lang::Bash;
    }

    if trimmed.contains("<?php") {
        return Lang::Php;
    }
    if trimmed.contains("package main") {
        return Lang::Go;
    }
    if trimmed.contains("fn main") && (trimmed.contains("println!") || trimmed.contains("fn main")) {
        // rust
        // Need to ensure not kotlin fun main? kotlin fun main also contains "fun main" but rust is "fn main"
        return Lang::Rust;
    }
    if lower.contains("use std::") {
        return Lang::Rust;
    }
    if trimmed.contains("public class") {
        return Lang::Java;
    }
    if trimmed.starts_with("#include") {
        // Could be C or Cpp: if contains <iostream> or std:: -> cpp, else cpp? Original '#include <stdio.h>' gave cpp in code detection? Actually for code "#include <stdio.h>" detection gave cpp (error linking). So #include gives cpp regardless.
        return Lang::Cpp;
    }
    if lower.starts_with("import os") || lower.starts_with("import sys") || lower.contains("\nimport os") || lower.contains("\nimport sys") {
        return Lang::Python;
    }
    if trimmed.starts_with("from ") && trimmed.contains(" import ") {
        return Lang::Python;
    }
    if trimmed.starts_with("def ") || trimmed.contains("\ndef ") {
        return Lang::Python;
    }
    if trimmed.starts_with("class ") {
        // Check if python class (has colon) vs java? For "class Foo: pass" it's python. For "class Main {", java.
        // We'll check if contains "{" -> java, else python if contains ":"
        if trimmed.contains("{") {
            return Lang::Java;
        }
        return Lang::Python;
    }
    if trimmed.contains("console.log") {
        return Lang::JavaScript;
    }
    if trimmed.starts_with("function ") {
        return Lang::JavaScript;
    }
    if lower.starts_with("puts ") || lower.starts_with("puts \"") || lower.starts_with("puts '") {
        // ruby
        return Lang::Ruby;
    }
    if trimmed.starts_with("IO.puts") {
        return Lang::Elixir;
    }
    if trimmed.starts_with("defmodule") {
        return Lang::Elixir;
    }
    if trimmed.starts_with("println \"") && !trimmed.contains("println!") {
        return Lang::Groovy;
    }
    if trimmed.starts_with("println(") {
        // Could be julia or kotlin? Heuristic: if contains "!void" or "std" => zig? But we have separate.
        // From observed: println("hi") => julia, println("hi") // kotlin? gave julia, but fun main => kotlin
        // So println( alone => julia
        return Lang::Julia;
    }
    if trimmed.starts_with("fun main") {
        return Lang::Kotlin;
    }
    if trimmed.starts_with("void main") {
        return Lang::Dart;
    }
    if trimmed.contains("@import(\"std\")") || trimmed.starts_with("const std = @import") {
        return Lang::Zig;
    }
    if trimmed.starts_with("let ") && (trimmed.contains("=") || trimmed.ends_with(";")) {
        // could be haskell or JS? Original "let x=1" gave haskell, "let x=1;" also haskell? Let's return haskell for let without JS detection
        // But JS also uses let. However console.log would have already matched js.
        // We'll return Haskell for "let" if not js.
        return Lang::Haskell;
    }
    if trimmed.starts_with("main = putStrLn") || trimmed.contains("putStrLn") {
        return Lang::Haskell;
    }
    if trimmed.contains("System.out.println") {
        // Original returned python for this? Actually earlier we saw System.out.println gave python NameError, but with fake detection we thought python. So maybe not java?
        // Let's keep python fallback for this to match earlier observed behavior: "System.out.println" gave python error, not java.
        // So don't detect java for System.out.println alone.
    }
    // Python fallback heuristics for print with import?
    // Lua detection for print('hi')
    if lower.starts_with("print(") || lower.starts_with("print \"") || lower.starts_with("print '") {
        // If contains import, it's python (already checked), else lua
        // Check if code contains "import" anywhere, then python
        if lower.contains("import") {
            return Lang::Python;
        }
        return Lang::Lua;
    }
    // If contains "echo" with quotes, original gave php?
    if lower.starts_with("echo '") || lower.starts_with("echo \"") {
        return Lang::Php;
    }

    // fallback python
    Lang::Python
}

