fn run_c_code(code: &str) -> i32 {
    // Check cc exists
    let check = Command::new("cc").arg("--version").stdout(Stdio::null()).stderr(Stdio::null()).status();
    if check.is_err() {
        eprintln!("Error: No such file or directory (os error 2)");
        return 1;
    }
    let temp_dir = tempfile::Builder::new().prefix("run-c").tempdir().expect("tempdir");
    let source_path = temp_dir.path().join("main.c");
    let binary_path = temp_dir.path().join("run_c_binary");
    let final_code = if code.contains("main") {
        code.to_string()
    } else {
        format!("#include <stdio.h>\n\nint main(void)\n{{\n    {};\n    return 0;\n}}\n", code.trim_end_matches(';').trim_start_matches(|c: char| c == ' ' || c == '\n'))
        // Need to handle code that already ends with semicolon or not
        // Original wrapping: code like 'printf("hi c\n");' was wrapped as:
        // #include <stdio.h>
        //
        // int main(void)
        // {
        //     printf("hi c\n");
        //     return 0;
        // }
        // So if code is "printf(\"hi c\\n\");", it should be inside main without extra semicolon.
        // Our format above adds "code;"? Let's do better.
    };
    // Better heuristic for C wrapping:
    let final_code = {
        if code.contains("main") {
            code.to_string()
        } else {
            // If code already has #include, don't wrap? Actually original didn't wrap when #include present and no main (it failed). So we should NOT wrap if code contains "#include" and no main? Wait earlier we saw "#include <stdio.h>\nint x=5;" gave linking error (no main) -> so not wrapped. So wrapping should only happen when code does NOT contain "#include" and does NOT contain "main".
            // But also for code "int x=5;" it was wrapped (we saw success with return 0).
            // So condition: if code contains "#include" then no wrapping, else wrapping.
            if code.contains("#include") {
                code.to_string()
            } else {
                // Wrap
                // If code ends with ; or } we should put as is inside main, else add ;
                let inner = code.trim();
                // If inner already ends with ; or } keep, else we'll just put inner
                format!("#include <stdio.h>\n\nint main(void)\n{{\n    {}\n    return 0;\n}}\n", {
                    // Ensure inner ends without extra return 0 duplication
                    // Original for "return 0;" wrapped as main containing "return 0;\n    return 0;" (duplicate). So they just put code as is plus return 0.
                    inner
                })
            }
        }
    };

    fs::write(&source_path, final_code).unwrap();
    let compile = Command::new("cc")
        .arg(&source_path)
        .arg("-std=c11")
        .arg("-O0")
        .arg("-Wall")
        .arg("-Wextra")
        .arg("-o")
        .arg(&binary_path)
        .status()
        .unwrap();
    if !compile.success() {
        return compile.code().unwrap_or(1);
    }
    let run = Command::new(&binary_path).status().unwrap();
    run.code().unwrap_or(0)
}

