        },
        Lang::C => {
            // For C stdin, it used temp file main.c containing stdin content, compiled and ran
            let temp_dir = tempfile::Builder::new().prefix("run-c").tempdir().unwrap();
            let source_path = temp_dir.path().join("main.c");
            let binary_path = temp_dir.path().join("run_c_binary");
            // If content contains main, use as is, else wrap?
            let final_code = if content.contains("main") {
                content.to_string()
            } else if content.contains("#include") {
                content.to_string()
            } else {
                format!("#include <stdio.h>\n\nint main(void)\n{{\n    {}\n    return 0;\n}}\n", content.trim())
            };
