impl Lang {
    fn from_str(s: &str) -> Option<Lang> {
        let lower = s.to_lowercase();
        match lower.as_str() {
            "bash" | "sh" | "shell" | "zsh" => Some(Lang::Bash),
            "c" => Some(Lang::C),
            "cpp" | "c++" => Some(Lang::Cpp),
            "crystal" | "cr" => Some(Lang::Crystal),
            "csharp" | "c#" | "cs" => Some(Lang::CSharp),
            "dart" => Some(Lang::Dart),
            "elixir" | "ex" | "exs" => Some(Lang::Elixir),
            "go" | "golang" => Some(Lang::Go),
            "groovy" => Some(Lang::Groovy),
            "haskell" | "hs" => Some(Lang::Haskell),
            "java" => Some(Lang::Java),
            "javascript" | "js" | "node" | "nodejs" => Some(Lang::JavaScript),
            "julia" | "jl" => Some(Lang::Julia),
            "kotlin" | "kt" => Some(Lang::Kotlin),
            "lua" => Some(Lang::Lua),
            "nim" => Some(Lang::Nim),
            "perl" | "pl" => Some(Lang::Perl),
            "php" => Some(Lang::Php),
            "python" | "python3" | "py" | "py3" => Some(Lang::Python),
            "r" | "rscript" => Some(Lang::R),
            "ruby" | "rb" => Some(Lang::Ruby),
            "rust" | "rs" => Some(Lang::Rust),
            "swift" => Some(Lang::Swift),
            "typescript" | "ts" => Some(Lang::TypeScript),
            "zig" => Some(Lang::Zig),
            _ => None,
        }
    }
    fn extension_map(ext: &str) -> Option<Lang> {
        let e = ext.to_lowercase();
        match e.as_str() {
            "py" | "py3" | "pyw" => Some(Lang::Python),
            "sh" | "bash" | "zsh" => Some(Lang::Bash),
            "c" => Some(Lang::C),
            "cpp" | "cc" | "hpp" => Some(Lang::Cpp),
            "go" => Some(Lang::Go),
            "rs" => Some(Lang::Rust),
            "js" | "mjs" | "cjs" | "jsx" => Some(Lang::JavaScript),
            "ts" | "tsx" => Some(Lang::TypeScript),
            "java" => Some(Lang::Java),
            "kt" | "kts" => Some(Lang::Kotlin),
            "swift" => Some(Lang::Swift),
            "rb" => Some(Lang::Ruby),
            "php" => Some(Lang::Php),
            "pl" | "pm" => Some(Lang::Perl),
            "lua" => Some(Lang::Lua),
            "nim" => Some(Lang::Nim),
            "zig" => Some(Lang::Zig),
            "dart" => Some(Lang::Dart),
            "cr" => Some(Lang::Crystal),
            "ex" | "exs" => Some(Lang::Elixir),
            "groovy" => Some(Lang::Groovy),
            "hs" => Some(Lang::Haskell),
            "jl" => Some(Lang::Julia),
            "r" => Some(Lang::R),
            "cs" => Some(Lang::CSharp),
            _ => None,
        }
    }
}

fn is_file_path_arg(arg: &str) -> bool {
    if Path::new(arg).exists() {
        return true;
    }
    if arg.contains('/') || arg.contains('\\') {
        return true;
    }
    if let Some(ext) = Path::new(arg).extension().and_then(|e| e.to_str()) {
        let el = ext.to_lowercase();
        // file extensions that are considered file even without slash and without existence
        // Observed: py, sh, c, cpp, rs, go, rb, js, ts, java, kt, pl, bash, zsh, cs? Check list
        // For py, sh, c, cpp, rs, go, rb, js, ts, java, kt, pl, bash, zsh -> file
        // For others like dart, lua, nim, zig, php, swift, jl, cr, ex, groovy, hs, r, txt, md -> code
        match el.as_str() {
            "py" | "py3" | "pyw" | "sh" | "bash" | "zsh" | "c" | "cpp" | "cc" | "hpp" | "rs" | "go" | "rb" | "js" | "ts" | "java" | "kt" | "kts" | "pl" | "pm" | "cs" => true,
            _ => false,
        }
    } else {
        false
    }
}

fn lang_from_file_path(path: &str) -> Lang {
    if let Some(ext) = Path::new(path).extension().and_then(|e| e.to_str()) {
        if let Some(l) = Lang::extension_map(ext) {
            return l;
        }
    }
    Lang::Python
}

fn heuristic_detect_code(code: &str) -> Lang {
    let trimmed = code.trim();
    let lower = trimmed.to_lowercase();
    if trimmed.starts_with("#!") {
        let first_line = trimmed.lines().next().unwrap_or("").to_lowercase();
        if first_line.contains("bash") || first_line.contains("/sh") {
            if first_line.contains("bash") || first_line.contains(" sh") || first_line.ends_with("sh") {
                return Lang::Bash;
            }
        }
        if first_line.contains("perl") {
            return Lang::Perl;
        }
        if first_line.contains("ruby") {
            return Lang::Ruby;
        }
        if first_line.contains("node") {
            return Lang::JavaScript;
        }
        if first_line.contains("lua") {
            return Lang::Lua;
        }
        if first_line.contains("php") {
            return Lang::Php;
        }
    }
    if lower.starts_with("echo ") {
        let after = trimmed[4..].trim_start();
        let mut rest = after;
        if rest.starts_with("-") {
            if let Some(idx) = rest.find(' ') {
                rest = rest[idx..].trim_start();
            } else {
                rest = "";
            }
        }
        if !rest.is_empty() {
            let fc = rest.chars().next().unwrap();
            if fc != '\'' && fc != '"' {
                return Lang::Bash;
            }
        }
    }
    if lower.starts_with("export ") {
        return Lang::Bash;
    }
    if trimmed.contains("<?php") {
        return Lang::Php;
    }
    if trimmed.contains("package main") {
        return Lang::Go;
    }
    if trimmed.contains("fn main") && trimmed.contains("println!") {
        return Lang::Rust;
    }
    if lower.contains("use std::") {
        return Lang::Rust;
    }
    if trimmed.contains("public class") {
        return Lang::Java;
    }
    if trimmed.starts_with("#include") {
        return Lang::Cpp;
    }
    if lower.starts_with("import os") || lower.starts_with("import sys") || lower.contains("\nimport os") || lower.contains("\nimport sys") {
        return Lang::Python;
    }
    if trimmed.starts_with("from ") && trimmed.contains(" import ") {
        return Lang::Python;
    }
    if trimmed.starts_with("def ") || trimmed.contains("\ndef ") {
        return Lang::Python;
    }
    if trimmed.starts_with("class ") {
        if trimmed.contains("{") {
            return Lang::Java;
        }
        return Lang::Python;
    }
    if trimmed.contains("console.log") {
        return Lang::JavaScript;
    }
    if trimmed.starts_with("function ") {
        return Lang::JavaScript;
    }
    if lower.starts_with("puts ") || lower.starts_with("puts \"") || lower.starts_with("puts '") {
        return Lang::Ruby;
    }
    if trimmed.starts_with("IO.puts") {
        return Lang::Elixir;
    }
    if trimmed.starts_with("defmodule") {
        return Lang::Elixir;
    }
    if trimmed.starts_with("println \"") && !trimmed.contains("println!") {
        return Lang::Groovy;
    }
    if trimmed.starts_with("println(") {
        return Lang::Julia;
    }
    if trimmed.starts_with("fun main") {
        return Lang::Kotlin;
    }
    if trimmed.starts_with("void main") {
        return Lang::Dart;
    }
    if trimmed.contains("@import(\"std\")") || trimmed.starts_with("const std = @import") {
        return Lang::Zig;
    }
    if trimmed.starts_with("let ") {
        return Lang::Haskell;
    }
    if trimmed.starts_with("main = putStrLn") || trimmed.contains("putStrLn") {
        return Lang::Haskell;
    }
    if lower.starts_with("print(") {
        if lower.contains("import") {
            return Lang::Python;
        }
        return Lang::Lua;
    }
    if lower.starts_with("echo '") || lower.starts_with("echo \"") {
        return Lang::Php;
    }
    Lang::Python
}

