fn run_bash_code(code: &str) -> i32 {
    match Command::new("bash").arg("-c").arg(code).status() {
        Ok(st) => st.code().unwrap_or(1),
        Err(_) => {
            eprintln!("Error: No such file or directory (os error 2)");
            1
        }
    }
}
