fn run_c_code(code: &str) -> i32 {
    let _ = Command::new("cc").arg("--version").stdout(Stdio::null()).stderr(Stdio::null()).status();
    let temp_dir = match tempfile::Builder::new().prefix("run-c").tempdir() {
        Ok(d) => d,
        Err(_) => return 1,
    };
    let source_path = temp_dir.path().join("main.c");
    let binary_path = temp_dir.path().join("run_c_binary");
    let final_code = if code.contains("main") || code.contains("#include") {
        code.to_string()
    } else {
        format!("#include <stdio.h>\n\nint main(void)\n{{\n    {}\n    return 0;\n}}\n", code.trim())
    };
    if fs::write(&source_path, final_code).is_err() {
        return 1;
    }
    let compile = Command::new("cc")
        .arg(&source_path)
        .arg("-std=c11")
        .arg("-O0")
        .arg("-Wall")
        .arg("-Wextra")
        .arg("-o")
        .arg(&binary_path)
        .status();
    match compile {
        Ok(st) if st.success() => {},
        Ok(st) => return st.code().unwrap_or(1),
        Err(_) => {
            eprintln!("Error: No such file or directory (os error 2)");
            return 1;
        }
    }
    match Command::new(&binary_path).status() {
        Ok(st) => st.code().unwrap_or(0),
        Err(_) => 1,
    }
}
