fn run_unsupported(lang: &Lang, mode: &str) -> i32 {
    match lang {
        Lang::Crystal => {
            eprintln!("Error: Crystal support requires the `crystal` executable. Install it from https://crystal-lang.org/install/ and ensure it is on your PATH.");
        },
        Lang::CSharp => {
            // Check dotnet exists
            let dotnet_exists = Command::new("dotnet").arg("--list-sdks").stdout(Stdio::null()).stderr(Stdio::null()).status().is_ok();
            // Even if exists, original gave Unable to detect framework when file mode? For code mode, it gave requires dotnet CLI when dotnet missing, else Unable?
            // Let's mimic: if dotnet binary not found, error about dotnet CLI, else Unable.
            let check_which = Command::new("which").arg("dotnet").stdout(Stdio::null()).stderr(Stdio::null()).status();
            let dotnet_found = check_which.map(|s| s.success()).unwrap_or(false) || dotnet_exists;
            if dotnet_found {
                eprintln!("Error: Unable to detect installed .NET SDK target framework");
            } else {
                eprintln!("Error: C# support requires the `dotnet` CLI. Install the .NET SDK from https://dotnet.microsoft.com/download and ensure `dotnet` is on your PATH.");
            }
        },
        Lang::Dart => {
            eprintln!("Error: Dart support requires the `dart` executable. Install the Dart SDK from https://dart.dev/get-dart and ensure `dart` is on your PATH.");
        },
        Lang::Elixir => {
            eprintln!("Error: Elixir support requires the `elixir` executable. Install Elixir from https://elixir-lang.org/install.html and ensure `elixir` is on your PATH.");
        },
        Lang::Groovy => {
            eprintln!("Error: Groovy support requires the `groovy` executable. Install it from https://groovy-lang.org/download.html and make sure it is available on your PATH.");
        },
        Lang::Haskell => {
            eprintln!("Error: Haskell support requires the `runghc` executable. Install the GHC toolchain from https://www.haskell.org/ghc/ (or via ghcup) and ensure `runghc` is on your PATH.");
        },
        Lang::Java => {
            // For java file copy errors already handled before calling here
            eprintln!("Error: Java support requires the `javac` compiler. Install the JDK from https://adoptium.net/ or your vendor of choice and ensure it is on your PATH.");
        },
        Lang::Julia => {
            eprintln!("Error: Julia support requires the `julia` executable. Install Julia from https://julialang.org/downloads/ and ensure `julia` is on your PATH.");
        },
        Lang::Kotlin => {
            // If file doesn't exist, we already printed copy error before
            eprintln!("Error: Kotlin support requires the `kotlinc` compiler. Install it from https://kotlinlang.org/docs/command-line.html and ensure it is on your PATH.");
        },
        Lang::Lua => {
            eprintln!("Error: Lua support requires the `lua` executable. Install it from https://www.lua.org/download.html and ensure it is on your PATH.");
        },
        Lang::Nim => {
            if mode == "file" {
                // If file not exists, original gave No such file error for nim file mode
                // We handle existence before, but if exists and tool missing, gives requires error
                // For nonexistent, we already handled in run_file for nim file
