        }
        if first_line.contains("ruby") {
            return Lang::Ruby;
        }
        if first_line.contains("node") {
            return Lang::JavaScript;
        }
        if first_line.contains("lua") {
            return Lang::Lua;
        }
        if first_line.contains("php") {
            return Lang::Php;
        }
    }
