    let mut positional: Vec<String> = Vec::new();
    let mut i = 1;
    while i < args.len() {
        let arg = &args[i];
        if arg == "--" {
            i += 1;
            while i < args.len() {
                positional.push(args[i].clone());
                i += 1;
            }
            break;
        }
        if arg == "-V" || arg == "--version" {
            print!("{}", VERSION);
            return;
        }
        if arg == "-h" || arg == "--help" {
            print!("{}", HELP);
            return;
        }
        if arg == "--no-detect" {
            no_detect = true;
            i += 1;
            continue;
        }
        if arg == "-l" || arg == "--lang" {
            if i + 1 >= args.len() {
                eprint!("error: a value is required for '--lang <LANG>' but none was supplied\n\nFor more information, try '--help'.\n");
                std::process::exit(2);
            }
            lang_flag = Some(args[i+1].clone());
            i += 2;
            continue;
        }
        if let Some(v) = arg.strip_prefix("--lang=") {
            if v.is_empty() {
                eprint!("error: a value is required for '--lang <LANG>' but none was supplied\n\nFor more information, try '--help'.\n");
                std::process::exit(2);
            }
            lang_flag = Some(v.to_string());
            i += 1;
            continue;
        }
        if arg == "-f" || arg == "--file" {
            if i + 1 >= args.len() {
                eprint!("error: a value is required for '--file <PATH>' but none was supplied\n\nFor more information, try '--help'.\n");
                std::process::exit(2);
            }
            file_flag = Some(args[i+1].clone());
            i += 2;
            continue;
        }
        if let Some(v) = arg.strip_prefix("--file=") {
            if v.is_empty() {
                eprint!("error: a value is required for '--file <PATH>' but none was supplied\n\nFor more information, try '--help'.\n");
                std::process::exit(2);
            }
            file_flag = Some(v.to_string());
            i += 1;
            continue;
        }
        if arg == "-c" || arg == "--code" {
            if i + 1 >= args.len() {
                eprint!("error: a value is required for '--code <CODE>' but none was supplied\n\nFor more information, try '--help'.\n");
                std::process::exit(2);
            }
            code_flag = Some(args[i+1].clone());
            i += 2;
            continue;
        }
        if let Some(v) = arg.strip_prefix("--code=") {
            if v.is_empty() {
                eprint!("error: a value is required for '--code <CODE>' but none was supplied\n\nFor more information, try '--help'.\n");
                std::process::exit(2);
            }
            code_flag = Some(v.to_string());
            i += 1;
            continue;
        }
        if arg.starts_with('-') {
            let usage = if file_flag.is_some() && code_flag.is_some() {
                "executable --lang <LANG> --code <CODE> --file <PATH> [ARGS]"
            } else if file_flag.is_some() && lang_flag.is_some() {
                "executable --lang <LANG> --file <PATH> [ARGS]"
            } else if code_flag.is_some() && lang_flag.is_some() {
                "executable --lang <LANG> --code <CODE> [ARGS]"
            } else if file_flag.is_some() {
                "executable --file <PATH> [ARGS]"
            } else if lang_flag.is_some() {
                "executable --lang <LANG> [ARGS]"
            } else {
                "executable [OPTIONS] [ARGS]"
            };
            eprint!("error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\nUsage: {}...\n\nFor more information, try '--help'.\n", arg, arg, arg, usage);
            std::process::exit(2);
        }
        positional.push(arg.clone());
        i += 1;
    }

    if file_flag.is_some() && code_flag.is_some() {
        eprintln!("Error: --code/--inline cannot be combined with --file");
        std::process::exit(1);
    }
    if file_flag.is_some() && !positional.is_empty() {
        eprintln!("Error: Unexpected positional arguments when --file is present");
        std::process::exit(1);
    }
    if code_flag.is_some() && !positional.is_empty() {
        eprintln!("Error: Unexpected positional arguments after specifying --code");
        std::process::exit(1);
    }

    let mut lang_from_flag: Option<Lang> = None;
    if let Some(lf) = &lang_flag {
        if let Some(l) = Lang::from_str(lf) {
            lang_from_flag = Some(l);
        } else {
            print_unknown_lang_error(lf);
            std::process::exit(1);
        }
    }

    if let Some(file_path) = file_flag {
        let lang = if let Some(l) = lang_from_flag {
            l
        } else {
            if no_detect {
                Lang::Python
            } else {
                lang_from_file_path(&file_path)
            }
        };
        let final_lang = if no_detect && lang_flag.is_none() {
            Lang::Python
        } else {
            lang
        };
        std::process::exit(run_file(&final_lang, &file_path));
    }

    if let Some(code_str) = code_flag {
        let lang = if let Some(l) = lang_from_flag {
            l
        } else {
            if no_detect {
                Lang::Python
            } else {
                heuristic_detect_code(&code_str)
            }
        };
        std::process::exit(run_code(&lang, &code_str));
    }

    if positional.is_empty() {
        let mut stdin_content = String::new();
        if !io::stdin().is_terminal() {
            io::stdin().read_to_string(&mut stdin_content).unwrap();
        } else {
            std::process::exit(0);
        }
        if stdin_content.trim().is_empty() {
            std::process::exit(0);
        }
        let lang = if let Some(l) = lang_from_flag {
            l
        } else {
            if no_detect {
                Lang::Python
            } else {
                heuristic_detect_code(&stdin_content)
            }
        };
        std::process::exit(run_stdin(&lang, &stdin_content));
    } else if positional.len() == 1 {
        let arg = &positional[0];
        if arg == "--code" || arg == "--inline" {
            eprintln!("Error: --code/--inline requires a code argument");
            std::process::exit(1);
        }
        let is_file = is_file_path_arg(arg);
        if is_file {
            let lang = if let Some(l) = lang_from_flag.clone() {
                l
            } else {
                if no_detect {
                    Lang::Python
                } else {
                    lang_from_file_path(arg)
                }
            };
            let final_lang = if no_detect && lang_flag.is_none() {
                Lang::Python
            } else {
                lang
            };
            std::process::exit(run_file(&final_lang, arg));
        } else {
            if lang_from_flag.is_some() {
                std::process::exit(run_code(&lang_from_flag.unwrap(), arg));
            } else if let Some(l) = Lang::from_str(arg) {
                let mut stdin_content = String::new();
                if !io::stdin().is_terminal() {
                    io::stdin().read_to_string(&mut stdin_content).unwrap();
                } else {
                    std::process::exit(0);
                }
                if stdin_content.trim().is_empty() {
                    std::process::exit(0);
                }
                std::process::exit(run_stdin(&l, &stdin_content));
            } else {
                let lang = if no_detect {
                    Lang::Python
                } else {
                    heuristic_detect_code(arg)
                };
                std::process::exit(run_code(&lang, arg));
            }
        }
    } else {
        if lang_flag.is_none() {
            if let Some(first_lang) = Lang::from_str(&positional[0]) {
                if positional.len() == 2 {
                    let second = &positional[1];
                    if is_file_path_arg(second) {
                        std::process::exit(run_file(&first_lang, second));
                    } else {
                        std::process::exit(run_code(&first_lang, second));
                    }
                } else {
                    let code = positional[1..].join(" ");
                    std::process::exit(run_code(&first_lang, &code));
                }
            } else {
                let code = positional.join(" ");
                let lang = if no_detect {
                    Lang::Python
                } else {
                    heuristic_detect_code(&code)
                };
                std::process::exit(run_code(&lang, &code));
            }
        } else {
            let code = positional.join(" ");
            if code.trim().is_empty() {
                let mut stdin_content = String::new();
                if !io::stdin().is_terminal() {
                    io::stdin().read_to_string(&mut stdin_content).unwrap();
                }
                if !stdin_content.trim().is_empty() {
                    std::process::exit(run_stdin(&lang_from_flag.unwrap(), &stdin_content));
                } else {
                    std::process::exit(0);
                }
            }
            std::process::exit(run_code(&lang_from_flag.unwrap(), &code));
        }
    }
}
