fn run_go_file(path: &str) -> i32 {
    // For go file, attempt go run path with PWD /tmp and GO111MODULE=off
    // If fails due to file not found, go itself prints error, but for our earlier observed case with relative path and file not exists, original gave custom error "failed to invoke /usr/local/go/bin/go to run a.go"
    // Let's mimic: if file doesn't exist, we produce custom error for relative paths? Actually original behavior:
    // For "/tmp/nonexistent.go" (absolute slash) -> go prints "stat nonexistent.go: no such file or directory"
    // For "a.go" (no slash) -> custom error "failed to invoke /usr/local/go/bin/go to run a.go"
    // So difference is slash?
    // Let's implement: if !Path::exists && !path.contains('/') -> custom error, else let go run attempt.
    if !Path::new(path).exists() && !path.contains('/') {
        eprintln!("Error: failed to invoke /usr/local/go/bin/go to run {}\n\nCaused by:\n    No such file or directory (os error 2)", path);
        return 1;
    }
    let mut cmd = Command::new("go");
    cmd.arg("run").arg(path).current_dir("/tmp").env("GO111MODULE","off");
    match cmd.status() {
        Ok(st) => st.code().unwrap_or(1),
        Err(e) => {
            eprintln!("Error: failed to invoke /usr/local/go/bin/go to run {}\n\nCaused by:\n    {}", path, e);
            1
        }
    }
}
