fn run_unsupported(lang: &Lang, mode: &str) -> i32 {
    match lang {
        Lang::Crystal => { eprintln!("Error: Crystal support requires the `crystal` executable. Install it from https://crystal-lang.org/install/ and ensure it is on your PATH."); },
        Lang::CSharp => {
            let dotnet_exists = Command::new("dotnet").arg("--list-sdks").stdout(Stdio::null()).stderr(Stdio::null()).status().is_ok();
            let check_which = Command::new("which").arg("dotnet").stdout(Stdio::null()).stderr(Stdio::null()).status();
            let dotnet_found = check_which.map(|s| s.success()).unwrap_or(false) || dotnet_exists;
            if dotnet_found {
                eprintln!("Error: Unable to detect installed .NET SDK target framework");
            } else {
                eprintln!("Error: C# support requires the `dotnet` CLI. Install the .NET SDK from https://dotnet.microsoft.com/download and ensure `dotnet` is on your PATH.");
            }
        },
        Lang::Dart => { eprintln!("Error: Dart support requires the `dart` executable. Install the Dart SDK from https://dart.dev/get-dart and ensure `dart` is on your PATH."); },
        Lang::Elixir => { eprintln!("Error: Elixir support requires the `elixir` executable. Install Elixir from https://elixir-lang.org/install.html and ensure `elixir` is on your PATH."); },
        Lang::Groovy => { eprintln!("Error: Groovy support requires the `groovy` executable. Install it from https://groovy-lang.org/download.html and make sure it is available on your PATH."); },
        Lang::Haskell => { eprintln!("Error: Haskell support requires the `runghc` executable. Install the GHC toolchain from https://www.haskell.org/ghc/ (or via ghcup) and ensure `runghc` is on your PATH."); },
        Lang::Java => { eprintln!("Error: Java support requires the `javac` compiler. Install the JDK from https://adoptium.net/ or your vendor of choice and ensure it is on your PATH."); },
        Lang::Julia => { eprintln!("Error: Julia support requires the `julia` executable. Install Julia from https://julialang.org/downloads/ and ensure `julia` is on your PATH."); },
        Lang::Kotlin => { eprintln!("Error: Kotlin support requires the `kotlinc` compiler. Install it from https://kotlinlang.org/docs/command-line.html and ensure it is on your PATH."); },
        Lang::Lua => { eprintln!("Error: Lua support requires the `lua` executable. Install it from https://www.lua.org/download.html and ensure it is on your PATH."); },
        Lang::Nim => { eprintln!("Error: Nim support requires the `nim` executable. Install it from https://nim-lang.org/install.html and ensure it is on your PATH."); },
        Lang::Php => { eprintln!("Error: PHP support requires the `php` CLI executable. Install PHP and ensure it is on your PATH."); },
        Lang::R => { eprintln!("Error: R support requires the `Rscript` executable. Install R from https://cran.r-project.org/ and ensure `Rscript` is on your PATH."); },
        Lang::Swift => { eprintln!("Error: Swift support requires the `swift` executable. Install Xcode command-line tools or the Swift toolchain from https://www.swift.org/download/ and ensure `swift` is on your PATH."); },
        Lang::Zig => { eprintln!("Error: Zig support requires the `zig` executable. Install it from https://ziglang.org/download/ and ensure it is on your PATH."); },
        Lang::JavaScript => {
            if mode == "stdin" {
                eprintln!("Error: failed to start node for stdin execution\n\nCaused by:\n    No such file or directory (os error 2)");
            } else {
                eprintln!("Error: No such file or directory (os error 2)");
            }
        },
        Lang::Ruby => {
            if mode == "stdin" {
                eprintln!("Error: failed to start ruby for stdin execution\n\nCaused by:\n    No such file or directory (os error 2)");
            } else {
                eprintln!("Error: No such file or directory (os error 2)");
            }
        },
        Lang::TypeScript => {
            if mode == "code" || mode == "stdin" {
                eprintln!("Error: failed to run Deno for inline execution because 'deno' was not found in PATH. Install Deno from https://deno.land/manual/getting_started/installation or ensure the binary is available on your PATH.");
            } else {
                eprintln!("Error: failed to run Deno for file execution because 'deno' was not found in PATH. Install Deno from https://deno.land/manual/getting_started/installation or ensure the binary is available on your PATH.");
            }
        },
        _ => { eprintln!("Error: No such file or directory (os error 2)"); }
    }
    1
}
fn run_code(lang: &Lang, code: &str) -> i32 {
    match lang {
        Lang::Bash => run_bash_code(code),
        Lang::Python => run_python_code(code),
        Lang::Perl => run_perl_code(code),
        Lang::C => run_c_code(code),
        Lang::Cpp => run_cpp_code(code),
        Lang::Go => run_go_code(code),
        Lang::Rust => run_rust_code(code),
        _ => run_unsupported(lang, "code"),
    }
}
