fn run_go_file(path: &str) -> i32 {
    let p = Path::new(path);
    if !p.exists() {
        if !path.contains('/') && !path.contains('\\') {
            eprintln!("Error: failed to invoke /usr/local/go/bin/go to run {}\n\nCaused by:\n    No such file or directory (os error 2)", path);
            return 1;
        }
        let parent = p.parent().unwrap_or(Path::new("/tmp"));
        let file_name = p.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or(path.to_string());
        let mut cmd = Command::new("go");
        cmd.arg("run").arg(&file_name).current_dir(parent).env("GO111MODULE","off");
        return match cmd.status() {
            Ok(st) => st.code().unwrap_or(1),
            Err(e) => { eprintln!("Error: failed to invoke /usr/local/go/bin/go to run {}\n\nCaused by:\n    {}", path, e); 1 }
        };
    }
    let parent = p.parent().unwrap_or(Path::new("/tmp"));
    let file_name = p.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or(path.to_string());
    let mut cmd = Command::new("go");
    cmd.arg("run").arg(&file_name).current_dir(parent).env("GO111MODULE","off");
    match cmd.status() {
        Ok(st) => st.code().unwrap_or(1),
        Err(e) => { eprintln!("Error: failed to invoke /usr/local/go/bin/go to run {}\n\nCaused by:\n    {}", path, e); 1 }
    }
}
